# Zero here-strings (Base64-verified payloads) | Low-RAM Safe (OPENBLAS=1)
# - Custom GLSL Living-Card Shader (real plasma/starlight motion INSIDE each 3D card!)
# - Live 3D spark emitters erupting straight out of every revealed card
# - Vectorized 24fps internal-card animation for both Shorts & 7-Chapter Full Readings
# - Soft Warm Irish (en-IE-EmilyNeural) / Australian (en-AU-NatashaNeural) Female Voice
# - Fixes OpenBLAS/Paging-File crash, YouTube 400 '>' bug, Gate 2 100% & Tunnel health
# ==============================================================================
param(
    [ValidateSet("Irish","Australian")]
    [string]$VoiceAccent = "Irish",
    [int]$FullReadingMinutes = 3
)
$ErrorActionPreference = "Continue"
[Net.ServicePointManager]::SecurityProtocol = [Net.SecurityProtocolType]::Tls12

$ProjectDir = "C:\Users\toome\Desktop\SovereignCore"
Set-Location $ProjectDir

# 1) PERMANENT OPENBLAS / PAGING-FILE CRASH FIX (caps numpy/OpenBLAS to 1 thread so 8GB RAM never exhausts commit limit!)
foreach ($v in @("OPENBLAS_NUM_THREADS","OMP_NUM_THREADS","MKL_NUM_THREADS","NUMEXPR_NUM_THREADS")) {
    [Environment]::SetEnvironmentVariable($v, "1", "Process")
    [Environment]::SetEnvironmentVariable($v, "1", "User")
}
$env:RCLONE_BIND = "0.0.0.0"

foreach ($d in @("$ProjectDir\Modules","$ProjectDir\static","$ProjectDir\static\card_voices","$ProjectDir\assets\tarot_deck","$ProjectDir\backups\quarantined_cartoon_cards","$ProjectDir\data","$ProjectDir\reports","$ProjectDir\logs")) {
    New-Item -ItemType Directory -Path $d -Force | Out-Null
}

function Write-B64File([string]$Path, [string]$B64) {
    $bytes = [System.Convert]::FromBase64String($B64)
    [System.IO.File]::WriteAllBytes($Path, $bytes)
    Write-Host "  [WROTE] $Path ($($bytes.Length) bytes)" -ForegroundColor DarkCyan
}

Write-Host "========================================================================" -ForegroundColor Cyan
Write-Host "  ORACLE SYSTEMS LLC // PHASE 31 LIVING 3D ENGINE (Voice: $VoiceAccent Female)" -ForegroundColor White
Write-Host "========================================================================" -ForegroundColor Cyan

# Release stale locks & trim RAM (also frees OpenBLAS/Git Credential Manager paging space)
Write-Host "`n>>> [1/9] Releasing stale locks & reclaiming RAM (OPENBLAS_NUM_THREADS=1 active)..." -ForegroundColor Cyan
Get-NetTCPConnection -LocalPort 8000 -State Listen -ErrorAction SilentlyContinue |
    Select-Object -ExpandProperty OwningProcess -Unique |
    ForEach-Object { Stop-Process -Id $_ -Force -ErrorAction SilentlyContinue }
Get-CimInstance Win32_Process | Where-Object { $_.Name -eq 'ffmpeg.exe' -or $_.CommandLine -match 'sovereign_daemon\.py|phase17_|render_real_full' } |
    ForEach-Object { Stop-Process -Id $_.ProcessId -Force -ErrorAction SilentlyContinue }
