if ($added -match $rx) {
    Write-Host "[ABORTED] Secret detected in staged diff! Resetting." -ForegroundColor Red
    git reset | Out-Null
} elseif (git diff --cached --name-only) {
    git commit -m "Phase 31 Living 3D Engine: Custom GLSL Internal-Card Plasma Shader, 3D Spark Emitters, Warm Irish/Australian Female Voice, OpenBLAS Low-RAM Fix & YouTube Sync Fix"
